    /*
     * Add to the Categories
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Product
     */
    public Product addToCategories( UUID parentId, Category addTo ) {
	    LOGGER.info("handling AssignCategoriesToProductEvent - " );
	    
	    Product parentEntity = repository.findById(parentId).get();
	    Category child = registry.project( Category.class, addTo.getCategoryId());
	    
	    parentEntity.getCategories().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Categories
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Product
     */
	public Product removeFromCategories( UUID parentId, Category removeFrom ) {
	    LOGGER.info("handling RemoveCategoriesFromProductEvent " );
	
	    Product parentEntity = repository.findById(parentId).get();
	    Category child = registry.project( Category.class, removeFrom.getCategoryId());
	    
	    parentEntity.getCategories().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

